import json, os
from pathlib import Path

IMG_EXT={'.jpg','.jpeg','.png','.gif','.webp','.bmp','.svg','.avif','.ico','.jfif'}

def is_valid_image(path: Path):
    if not path.exists():
        return False,'missing'
    if path.is_dir():
        return False,'is-dir'
    try:
        b=path.read_bytes()[:512]
    except Exception as e:
        return False,f'read-error:{e.__class__.__name__}'
    if len(b)==0:
        return False,'empty'
    # common signatures
    if b.startswith(b'\xff\xd8\xff'):
        return True,'jpeg'
    if b.startswith(b'\x89PNG\r\n\x1a\n'):
        return True,'png'
    if b.startswith(b'GIF87a') or b.startswith(b'GIF89a'):
        return True,'gif'
    if b.startswith(b'RIFF') and b[8:12]==b'WEBP':
        return True,'webp'
    if b.startswith(b'BM'):
        return True,'bmp'
    if b[:4]==b'\x00\x00\x01\x00':
        return True,'ico'
    if b.startswith(b'<svg') or b.lstrip().startswith(b'<svg') or b.lstrip().startswith(b'<?xml'):
        # quick svg check
        txt=path.read_text(encoding='utf-8',errors='ignore')[:1000].lower()
        if '<svg' in txt:
            return True,'svg'
    # html/js indicator
    low=b.lower()
    if b'<html' in low or b'<!doctype' in low:
        return False,'html-content'
    if b'function' in low or b'var ' in low or b'const ' in low:
        return False,'script-content'
    ext=path.suffix.lower()
    if ext and ext not in IMG_EXT:
        return False,f'non-image-ext:{ext}'
    return False,'unknown-bytes'

arts=json.load(open('data/articles.json',encoding='utf-8'))
broken=[]
for a in arts:
    p=a.get('image')
    if not p:
        broken.append({'href':a['href'],'image':p,'reason':'empty'})
        continue
    rel=p[2:] if p.startswith('./') else p
    rel=rel[1:] if rel.startswith('/') else rel
    path=Path(rel)
    ok,reason=is_valid_image(path)
    if not ok:
        broken.append({'href':a['href'],'image':p,'reason':reason})

print('total_articles',len(arts))
print('broken_thumbnails',len(broken))
from collections import Counter
print('reasons',Counter(b['reason'] for b in broken))
for b in broken[:100]:
