{"intent":"compute close filename matches for unresolved broken thumbnails","expect":"suggest best replacement images for all broken records","script":"python3 - <<'PY'
import os, json, re, difflib
from pathlib import Path

IMG_EXT={'.jpg','.jpeg','.png','.gif','.webp','.bmp','.svg','.avif','.ico','.jfif'}

def valid(path: Path):
    if not path.exists() or path.is_dir(): return False
    b=path.read_bytes()[:512]
    if not b: return False
    bl=b.lower()
    if b.startswith(b'\xff\xd8\xff') or b.startswith(b'\x89PNG\r\n\x1a\n') or b.startswith(b'GIF87a') or b.startswith(b'GIF89a') or (b.startswith(b'RIFF') and b[8:12]==b'WEBP') or b.startswith(b'BM'):
        return True
    if bl.lstrip().startswith(b'<svg') or bl.lstrip().startswith(b'<?xml'):
        return True
    return False

def reason(path: Path):
    if not path.exists(): return 'missing'
    if path.is_dir(): return 'is-dir'
    b=path.read_bytes()[:256].lower()
    if valid(path): return ''
    if b'<html' in b or b'<!doctype' in b: return 'html-content'
    return 'other'

# collect valid image basenames
valid_files=[]
for root,_,files in os.walk('assets'):
    for f in files:
        if Path(f).suffix.lower() not in IMG_EXT: continue
        p=Path(root)/f
        if valid(p):
            valid_files.append(str(p).replace('\\','/'))

base_map={}
for p in valid_files:
    base=Path(p).name
    base_map.setdefault(base.lower(),[]).append(p)
valid_bases=list(base_map.keys())

arts=json.load(open('data/articles.json',encoding='utf-8'))
broken=[]
for a in arts:
    p=a.get('image') or ''
    if not p: continue
    rel=p[2:] if p.startswith('./') else p
    rel=rel[1:] if rel.startswith('/') else rel
    r=reason(Path(rel))
    if r:
        broken.append((a['href'],p,r))

print('broken',len(broken))
for href,p,r in broken:
    base=Path(p).name.lower()
    exact=base_map.get(base,[])
    if exact:
        print('\nEXACT',href,'|',r,'|',p)
        for c in exact[:3]:print(' ->',c)
        continue
    close=difflib.get_close_matches(base,valid_bases,n=3,cutoff=0.66)
    if close:
        print('\nCLOSE',href,'|',r,'|',base)
        for cb in close:
            print(' ->',base_map[cb][0])
