import json,re
from pathlib import Path
from collections import Counter,defaultdict

ROOT=Path('.')
arts=json.load(open('data/articles.json',encoding='utf-8'))
img_re=re.compile(r'<img\b[^>]*\bsrc\s*=\s*(["\'])(.*?)\1',re.I|re.S)


def is_remote(src:str)->bool:
    s=src.strip().lower()
    return s.startswith('http://') or s.startswith('https://') or s.startswith('//') or s.startswith('data:') or s.startswith('mailto:') or s.startswith('tel:')


def resolve(page:Path, src:str)->Path:
    s=src.strip()
    if s.startswith('/'):
        return ROOT / s[1:]
    return (page.parent / s).resolve().relative_to(ROOT.resolve()) if True else page.parent/s


def sniff(path:Path):
    if not path.exists():
        return 'missing'
    if path.is_dir():
        return 'is-dir'
    b=path.read_bytes()[:1024]
    if not b:
        return 'empty'
    lb=b.lower()
    if b.startswith(b'\xff\xd8\xff'):
        return ''
    if b.startswith(b'\x89PNG\r\n\x1a\n'):
        return ''
    if b.startswith(b'GIF87a') or b.startswith(b'GIF89a'):
        return ''
    if b.startswith(b'RIFF') and b[8:12]==b'WEBP':
        return ''
    if b.startswith(b'BM'):
        return ''
    if b[:4]==b'\x00\x00\x01\x00':
        return ''
    if b'<svg' in lb:
        return ''
    if b'<html' in lb or b'<!doctype' in lb:
        return 'html-content'
    if b'function ' in lb or b'var ' in lb or b'const ' in lb:
        return 'script-content'
    return 'unknown-bytes'

issues=[]
for a in arts:
    page=Path(a['href'])
    if not page.exists():
        continue
    txt=page.read_text(encoding='utf-8',errors='ignore')
    for m in img_re.finditer(txt):
        src=m.group(2).strip()
        if not src or is_remote(src):
            continue
        try:
            p=(page.parent/src).resolve()
        except Exception:
            issues.append({'href':a['href'],'src':src,'reason':'resolve-error','path':''})
            continue
        rel=''
        try:
            rel=str(p.relative_to(ROOT.resolve())).replace('\\','/')
            path=Path(rel)
        except Exception:
            # escapes repo
            issues.append({'href':a['href'],'src':src,'reason':'outside-root','path':str(p)})
            continue
        reason=sniff(path)
        if reason:
            issues.append({'href':a['href'],'src':src,'reason':reason,'path':rel})

print('issues',len(issues))
print('reason_counts',Counter(i['reason'] for i in issues))
print('article_count',len({i['href'] for i in issues}))
for i,row in enumerate(issues[:80],1):
    print(f"{i:03d}",row['reason'],'|',row['href'],'| src=',row['src'],'| path=',row['path'])
